body.script:
function toast(msg){var t=document.getElementById('siteToast');if(!t)return;t.innerHTML=msg;t.className='toast show';clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(function(){t.className='toast';},3200);}
function toggleMenu(){var n=document.getElementById('mainNav'),b=document.getElementById('menuToggle');if(!n)return;var open=n.classList.toggle('mobile-open');if(open){n.style.display='flex';n.style.flexDirection='column';n.style.position='absolute';n.style.right='16px';n.style.top='70px';n.style.background='#fff';n.style.padding='16px';n.style.borderRadius='14px';n.style.boxShadow='0 10px 30px rgba(0,0,0,.12)';}else{n.style.display='';n.style.flexDirection='';n.style.position='';n.style.right='';n.style.top='';n.style.background='';n.style.padding='';n.style.borderRadius='';n.style.boxShadow='';}if(b){b.classList.toggle('active',open);b.setAttribute('aria-expanded',open?'true':'false');}}
function showStatus(id,msg){var e=document.getElementById(id);if(e){e.innerHTML=msg;e.className='form-status show';}}
function makeId(prefix){var d=new Date(),y=d.getFullYear(),r=Math.floor(1000+Math.random()*9000);return prefix+'-'+y+'-'+r;}
function submitJoinForm(e){e.preventDefault();var id=makeId('BYCN'),name=document.getElementById('joinName').value.trim();var rec={id:id,name:name,age:document.getElementById('joinAge').value,phone:document.getElementById('joinPhone').value,email:document.getElementById('joinEmail').value,address:document.getElementById('joinAddress').value,study:document.getElementById('joinStudy').value,reason:document.getElementById('joinReason').value,date:new Date().toISOString()};try{localStorage.setItem('bycn_membership_'+id,JSON.stringify(rec));localStorage.setItem('bycn_latest_member',JSON.stringify(rec));}catch(x){}var photo=document.getElementById('joinPhoto');if(photo&&photo.files&&photo.files[0]){var reader=new FileReader();reader.onload=function(ev){var img=document.getElementById('idPhotoPreview');if(img)img.src=ev.target.result;};reader.readAsDataURL(photo.files[0]);}document.getElementById('generatedMemberId').innerHTML=id;document.getElementById('generatedMemberName').innerHTML='Member: '+name;document.getElementById('idCardText').innerHTML=name+'<br/>'+id+' • '+rec.address+'<br/>✓ Application received';document.getElementById('joinResult').className='service-result show';showStatus('joinStatus','✓ Joining form submitted successfully. Your digital member ID has been created.');toast('✓ Membership submitted: '+id);document.getElementById('joinResult').scrollIntoView({behavior:'smooth',block:'center'});return false;}
function printMemberCard(){var card=document.getElementById('liveIdCard');if(!card)return;var w=window.open('','_blank','width=600,height=500');if(!w){toast('Please allow pop-ups to print your Digital ID.');return;}w.document.write('<html><head><title>Bote Youth Community Digital ID</title><style>body{font-family:Arial;padding:40px}.idcard{border:2px solid #003893;border-radius:16px;padding:25px;max-width:420px}.idphoto{width:90px;height:90px;object-fit:cover;float:right;border-radius:10px}</style></head><body>'+card.outerHTML+'</body></html>');w.document.close();w.focus();setTimeout(function(){w.print();},300);}
function submitScholarship(e){e.preventDefault();var id=makeId('BYCS'),rec={id:id,name:document.getElementById('schName').value.trim(),age:document.getElementById('schAge').value,phone:document.getElementById('schPhone').value,email:document.getElementById('schEmail').value,school:document.getElementById('schSchool').value,level:document.getElementById('schLevel').value,income:document.getElementById('schIncome').value,amount:document.getElementById('schAmount').value,reason:document.getElementById('schReason').value,date:new Date().toISOString()};try{localStorage.setItem('bycn_scholarship_'+id,JSON.stringify(rec));}catch(x){}showStatus('schStatus','✓ Scholarship application submitted successfully. Application reference: <strong>'+id+'</strong>. Please keep this number for follow-up.');toast('✓ Scholarship application submitted: '+id);document.getElementById('schStatus').scrollIntoView({behavior:'smooth',block:'center'});return false;}
function voteNotice(){var selected=document.querySelector('input[name="vote"]:checked');if(!selected)return false;var key='bycn_vote_'+selected.value;try{localStorage.setItem(key,String((parseInt(localStorage.getItem(key)||'0',10)+1)));}catch(x){}toast('✓ Thank you! Your community vote was recorded.');return false;}
function newsletterSubmit(e){e.preventDefault();var input=e.target.querySelector('input[type="email"]');if(!input||!input.value)return false;try{localStorage.setItem('bycn_newsletter_email',input.value);}catch(x){}toast('✓ Thank you! You joined the cultural newsletter.');e.target.reset();return false;}
function closeMobileMenu(){var n=document.getElementById('mainNav'),b=document.getElementById('menuToggle');if(window.innerWidth<901&&n&&n.classList.contains('mobile-open')){n.classList.remove('mobile-open');n.style.display='none';if(b){b.classList.remove('active');b.setAttribute('aria-expanded','false');}}}
window.addEventListener('scroll',function(){var h=document.querySelector('.header');if(h)h.classList.toggle('scrolled',window.scrollY>12);});
window.addEventListener('DOMContentLoaded',function(){v12Init();var nav=document.querySelectorAll('#mainNav a');for(var i=0;i<nav.length;i++){nav[i].addEventListener('click',closeMobileMenu);}var reveal=document.querySelectorAll('.section,.hero,.theme-note,.poll,.form-card,.feature,.tile,.leader,.side-widget');for(var j=0;j<reveal.length;j++)reveal[j].classList.add('reveal');if('IntersectionObserver' in window){var io=new IntersectionObserver(function(entries){for(var k=0;k<entries.length;k++)if(entries[k].isIntersecting){entries[k].target.classList.add('visible');io.unobserve(entries[k].target);}}, {threshold:.08});for(var q=0;q<reveal.length;q++)io.observe(reveal[q]);}else{for(var z=0;z<reveal.length;z++)reveal[z].classList.add('visible');}document.addEventListener('click',function(ev){var a=ev.target.closest?ev.target.closest('a'):null;if(!a)return;var href=a.getAttribute('href')||'';if(href.charAt(0)==='#'){var target=document.querySelector(href);if(target){ev.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'});closeMobileMenu();}}});try{var old=JSON.parse(localStorage.getItem('bycn_latest_member')||'null');if(old){document.getElementById('idCardText').innerHTML=old.name+'<br/>'+old.id+' • '+old.address+'<br/>✓ Saved Member';}}catch(x){}});

/* V12 editor functions */
var V12_DEFAULTS={general:{title:'BOTE YOUTH COMMUNITY',tag:'Preserving Heritage • Empowering the Future',hero:'Preserving Our River Heritage,\nEmpowering Bote Youth',heroDesc:'Official portal of the Bote Community of Karmaiya, Sarlahi District, Nepal. Safeguarding our ancient single-log canoe craft, revitalizing the endangered Tarahi Bote language, and funding education for the next generation.',member:'GET YOUR OFFICIAL BOTE YOUTH COMMUNITY DIGITAL IDENTITY CARD',memberDesc:'Register online in less than 2 minutes. Fill the form below to create your member ID and an instant printable digital card.',email:'navarajbot@gmail.com',phone:'+977-9806389212'},bento:{eyebrow:'BENTO GRID • COMMUNITY MATRIX',title:'BOTE YOUTH GRID OVERVIEW',sub:'Explore heritage, language, craftsmanship, council leaders, and digital identity through interconnected Bento modules.',badge:'INDIGENOUS HERITAGE • Karmaiya, Sarlahi • Bagmati River',featureTitle:'REVITALIZING ANCIENT WATER TRADITIONS &amp; YOUTH LEADERSHIP',featureDesc:'The Bote indigenous community honors ancestral river navigation, single-log dugout canoes (Ek-Dunge Nau), and sacred water rites while educating the next generation of Nepali leaders.'},pillars:[],leaders:[],events:[{date:'Coming Soon',title:'Bote Heritage &amp; River Culture Day',desc:'A community gathering celebrating canoe craftsmanship, river traditions, youth leadership, and cultural knowledge.',link:'#online-services'},{date:'Coming Soon',title:'Youth Leadership &amp; Education Program',desc:'Youth workshops connecting leadership development, education support, language preservation, and community service.',link:'#joining-form'},{date:'Coming Soon',title:'Tarahi Bote Language Preservation',desc:'Community language sessions for recording, teaching, and preserving Tarahi Bote words and oral traditions.',link:'#language'}],logo:{src:'https://via.placeholder.com/96x96.png?text=BOTE',alt:'BOTE YOUTH COMMUNITY Logo'}};
function v12Text(sel){var e=document.querySelector(sel);return e?e.textContent.trim():''}
function v12SetText(sel,val){var e=document.querySelector(sel);if(e)e.textContent=val||''}
function v12SetHTML(sel,val){var e=document.querySelector(sel);if(e)e.innerHTML=(val||'').replace(/\n/g,'<br/>')}
function v12OpenEditor(){var b=document.getElementById('v12EditorBackdrop');if(!b)return;b.classList.add('open');b.setAttribute('aria-hidden','false');v12BuildEditors();document.body.style.overflow='hidden'}
function v12CloseEditor(){var b=document.getElementById('v12EditorBackdrop');if(!b)return;b.classList.remove('open');b.setAttribute('aria-hidden','true');document.body.style.overflow=''}
function v12Store(){try{return JSON.parse(localStorage.getItem('bycn_v12_content')||'null')}catch(e){return null}}
function v12Get(){return v12Store()||JSON.parse(JSON.stringify(V12_DEFAULTS))}
function v12Save(obj){try{localStorage.setItem('bycn_v12_content',JSON.stringify(obj));return true}catch(e){toast('Could not save all changes. Browser storage may be full.');return false}}
function v12BuildEditors(){var d=v12Get();
var g=d.general||V12_DEFAULTS.general;document.getElementById('v12GeneralTitle').value=g.title||'';document.getElementById('v12GeneralTag').value=g.tag||'';document.getElementById('v12GeneralHero').value=g.hero||'';document.getElementById('v12GeneralHeroDesc').value=g.heroDesc||'';document.getElementById('v12GeneralMember').value=g.member||'';document.getElementById('v12GeneralMemberDesc').value=g.memberDesc||'';document.getElementById('v12GeneralEmail').value=g.email||'';document.getElementById('v12GeneralPhone').value=g.phone||'';
var b=d.bento||V12_DEFAULTS.bento;document.getElementById('v12BentoEyebrow').value=b.eyebrow||'';document.getElementById('v12BentoTitle').value=b.title||'';document.getElementById('v12BentoSub').value=b.sub||'';document.getElementById('v12BentoBadge').value=b.badge||'';document.getElementById('v12BentoFeatureTitle').value=b.featureTitle||'';document.getElementById('v12BentoFeatureDesc').value=b.featureDesc||'';
var infos=document.querySelectorAll('.info');var pe=document.getElementById('v12PillarsEditor');pe.innerHTML='';var pillars=d.pillars&&d.pillars.length?d.pillars:[];if(!pillars.length){for(var i=0;i<infos.length;i++){var inf=infos[i];pillars.push({title:(inf.querySelector('h3')||{}).textContent||'',desc:(inf.querySelector('p')||{}).textContent||'',link:(inf.querySelector('a')||{}).getAttribute?inf.querySelector('a').getAttribute('href'):'#culture'});}}d.pillars=pillars;for(var p=0;p<4;p++){var x=pillars[p]||{title:'',desc:'',link:'#culture'};pe.innerHTML+='<div class="v12-event-row"><div class="v12-field"><label>Pillar '+(p+1)+' title</label><input data-v12-p="'+p+'" data-k="title" value="'+v12Esc(x.title)+'"/></div><div class="v12-field"><label>Pillar description</label><textarea data-v12-p="'+p+'" data-k="desc">'+v12Esc(x.desc)+'</textarea></div><div class="v12-field"><label>Button link</label><input data-v12-p="'+p+'" data-k="link" value="'+v12Esc(x.link)+'"/></div></div>'}
var le=document.getElementById('v12LeadersEditor');le.innerHTML='';var leaders=d.leaders&&d.leaders.length?d.leaders:[];var cards=document.querySelectorAll('.leader');for(var j=0;j<10;j++){if(!leaders[j]){var c=cards[j];leaders[j]={name:c&&c.querySelector('h3')?c.querySelector('h3').textContent.trim():'Community Leader Name',np:c&&c.querySelector('.np')?c.querySelector('.np').textContent.trim():'नाम',role:c&&c.querySelector('.role')?c.querySelector('.role').textContent.replace('●','').trim():'Community Role',bio:c&&c.querySelector('p')?c.querySelector('p').textContent.trim():'Edit this profile details.',term:c&&c.querySelector('.leader-foot span')?c.querySelector('.leader-foot span').textContent.trim():'Term',photo:c&&c.querySelector('.avatar')?c.querySelector('.avatar').src:''}}d.leaders=leaders;var L=leaders[j];le.innerHTML+='<div class="v12-box"><h3>Leader '+(j+1)+'</h3><div class="v12-leader"><img id="v12LeaderPreview'+j+'" class="v12-photo" alt="Leader photo" src="'+v12Attr(L.photo||'')+'"/><div><div class="v12-field"><label>Name</label><input data-v12-leader="'+j+'" data-k="name" value="'+v12Esc(L.name)+'"/></div><div class="v12-field"><label>Nepali name</label><input data-v12-leader="'+j+'" data-k="np" value="'+v12Esc(L.np)+'"/></div><div class="v12-field"><label>Position / role</label><input data-v12-leader="'+j+'" data-k="role" value="'+v12Esc(L.role)+'"/></div><div class="v12-field"><label>Full profile description</label><textarea data-v12-leader="'+j+'" data-k="bio">'+v12Esc(L.bio)+'</textarea></div><div class="v12-field"><label>Term</label><input data-v12-leader="'+j+'" data-k="term" value="'+v12Esc(L.term)+'"/></div><div class="v12-field"><label>Upload / change profile photo</label><input type="file" accept="image/*" data-v12-photo="'+j+'"/></div></div></div></div>'}
var ee=document.getElementById('v12EventsEditor');ee.innerHTML='';var events=d.events&&d.events.length?d.events:[];for(var q=0;q<events.length;q++){var E=events[q];ee.innerHTML+='<div class="v12-event-row"><h3 style="font:800 13px Poppins,Arial;margin:0 0 10px;color:#071b3d">Event '+(q+1)+'</h3><div class="v12-grid"><div class="v12-field"><label>Date / label</label><input data-v12-event="'+q+'" data-k="date" value="'+v12Esc(E.date)+'"/></div><div class="v12-field"><label>Event title</label><input data-v12-event="'+q+'" data-k="title" value="'+v12Esc(E.title)+'"/></div></div><div class="v12-field"><label>Description</label><textarea data-v12-event="'+q+'" data-k="desc">'+v12Esc(E.desc)+'</textarea></div><div class="v12-field"><label>Event link</label><input data-v12-event="'+q+'" data-k="link" value="'+v12Esc(E.link)+'"/></div>'+(q>=3?'<button class="v12-btn light" type="button" onclick="v12RemoveEvent('+q+')">Remove Event</button>':'')+'</div>'}
var logo=d.logo||V12_DEFAULTS.logo;document.getElementById('v12LogoPreview').src=logo.src||V12_DEFAULTS.logo.src;document.getElementById('v12LogoAlt').value=logo.alt||V12_DEFAULTS.logo.alt;
}
function v12Esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function v12Attr(v){return v12Esc(v).replace(/'/g,'&#39;')}
function v12Collect(){var d=v12Get();d.general={title:document.getElementById('v12GeneralTitle').value,tag:document.getElementById('v12GeneralTag').value,hero:document.getElementById('v12GeneralHero').value,heroDesc:document.getElementById('v12GeneralHeroDesc').value,member:document.getElementById('v12GeneralMember').value,memberDesc:document.getElementById('v12GeneralMemberDesc').value,email:document.getElementById('v12GeneralEmail').value,phone:document.getElementById('v12GeneralPhone').value};d.bento={eyebrow:document.getElementById('v12BentoEyebrow').value,title:document.getElementById('v12BentoTitle').value,sub:document.getElementById('v12BentoSub').value,badge:document.getElementById('v12BentoBadge').value,featureTitle:document.getElementById('v12BentoFeatureTitle').value,featureDesc:document.getElementById('v12BentoFeatureDesc').value};d.pillars=d.pillars||[];document.querySelectorAll('[data-v12-p]').forEach(function(e){var i=parseInt(e.getAttribute('data-v12-p'),10),k=e.getAttribute('data-k');d.pillars[i]=d.pillars[i]||{};d.pillars[i][k]=e.value});d.leaders=d.leaders||[];document.querySelectorAll('[data-v12-leader]').forEach(function(e){var i=parseInt(e.getAttribute('data-v12-leader'),10),k=e.getAttribute('data-k');d.leaders[i]=d.leaders[i]||{};d.leaders[i][k]=e.value});d.events=[];document.querySelectorAll('[data-v12-event]').forEach(function(e){var i=parseInt(e.getAttribute('data-v12-event'),10),k=e.getAttribute('data-k');d.events[i]=d.events[i]||{};d.events[i][k]=e.value});d.logo=d.logo||{};d.logo.alt=document.getElementById('v12LogoAlt').value||'BOTE YOUTH COMMUNITY Logo';return d}
function v12Apply(d){var g=d.general||{};v12SetText('.brand-title',g.title);v12SetText('.brand-tag',g.tag);var hero=document.querySelector('.hero h1');if(hero){var parts=(g.hero||'').split(/\\n|\n/);hero.innerHTML=v12Esc(parts[0]||'')+'<br/><span class="gold">'+v12Esc(parts[1]||'')+'</span>'}v12SetText('.hero p',g.heroDesc);v12SetText('.membership h2',g.member);v12SetText('.membership p',g.memberDesc);var b=d.bento||{};var sec=document.querySelector('.section:not(.gray):not(.form-section):not(.v12-events)');if(sec){v12SetText(sec.querySelector('.eyebrow'),b.eyebrow);v12SetText(sec.querySelector('.title'),b.title);v12SetText(sec.querySelector('.sub'),b.sub);v12SetText(sec.querySelector('.feature .badge'),b.badge);v12SetText(sec.querySelector('.feature h3'),b.featureTitle);v12SetText(sec.querySelector('.feature p'),b.featureDesc)}var infos=document.querySelectorAll('.info');(d.pillars||[]).forEach(function(x,i){if(!infos[i])return;v12SetText(infos[i].querySelector('h3'),x.title);v12SetText(infos[i].querySelector('p'),x.desc);var a=infos[i].querySelector('a');if(a){a.textContent=(i===0?'Read History →':i===1?'Explore Rituals →':i===2?'Open Lexicon →':'View Culture →');a.setAttribute('href',x.link||'#culture')}});var cards=document.querySelectorAll('.leader');(d.leaders||[]).forEach(function(x,i){if(!cards[i])return;v12SetText(cards[i].querySelector('h3'),x.name);v12SetText(cards[i].querySelector('.np'),x.np);v12SetText(cards[i].querySelector('.role'),'● '+x.role);v12SetText(cards[i].querySelector('p'),x.bio);v12SetText(cards[i].querySelector('.leader-foot span'),x.term);if(x.photo){var im=cards[i].querySelector('.avatar');if(im)im.src=x.photo}});var eg=document.getElementById('v12EventGrid');if(eg){eg.innerHTML='';(d.events||[]).forEach(function(x,i){eg.innerHTML+='<article class="v12-event-card"><span class="v12-event-date">'+v12Esc(x.date||'Coming Soon')+'</span><h3>'+v12Esc(x.title||'Community Event')+'</h3><p>'+v12Esc(x.desc||'')+'</p><a href="'+v12Attr(x.link||'#online-services')+'">View Program →</a></article>'})}var email=g.email||'navarajbot@gmail.com',phone=g.phone||'+977-9806389212';var mailLinks=document.querySelectorAll('a[href^="mailto:"]');for(var mi=0;mi<mailLinks.length;mi++)mailLinks[mi].setAttribute('href','mailto:'+email);var telLinks=document.querySelectorAll('a[href^="tel:"]');for(var ti=0;ti<telLinks.length;ti++)telLinks[ti].setAttribute('href','tel:'+phone.replace(/[^0-9+]/g,''));var logo=d.logo||{};var ims=document.querySelectorAll('.brand-logo');for(var z=0;z<ims.length;z++){if(logo.src)ims[z].src=logo.src;if(logo.alt)ims[z].alt=logo.alt}}
function v12SaveAll(){var d=v12Collect();var files=document.querySelectorAll('[data-v12-photo]');var logoFile=document.getElementById('v12LogoFile');var pending=files.length+(logoFile&&logoFile.files&&logoFile.files[0]?1:0);var done=0;function finish(){done++;if(done>=pending){v12Save(d);v12Apply(d);v12BuildEditors();toast('✓ Website content saved on this browser.');}}if(!pending){v12Save(d);v12Apply(d);toast('✓ Website content saved on this browser.');return}for(var i=0;i<files.length;i++){(function(inp){if(!inp.files||!inp.files[0]){finish();return}var r=new FileReader();r.onload=function(ev){var n=parseInt(inp.getAttribute('data-v12-photo'),10);d.leaders[n].photo=ev.target.result;finish()};r.onerror=finish;r.readAsDataURL(inp.files[0])})(files[i])}if(logoFile&&logoFile.files&&logoFile.files[0]){var lr=new FileReader();lr.onload=function(ev){d.logo.src=ev.target.result;finish()};lr.onerror=finish;lr.readAsDataURL(logoFile.files[0])}}
function v12AddEvent(){var d=v12Collect();d.events=d.events||[];d.events.push({date:'New Date',title:'New Community Event',desc:'Add event details here.',link:'#online-services'});v12Save(d);v12BuildEditors();document.querySelector('[data-v12-tab="events"]').click();toast('✓ New event added.');}
function v12RemoveEvent(i){var d=v12Collect();if(d.events.length<=3)return;d.events.splice(i,1);v12Save(d);v12BuildEditors();toast('✓ Event removed.');}
function v12ResetChanges(){try{localStorage.removeItem('bycn_v12_content')}catch(e){}v12Apply(V12_DEFAULTS);v12BuildEditors();toast('↺ Saved content reset to original content.');}
function v12Init(){var d=v12Store();if(d)v12Apply(d);var tabs=document.querySelectorAll('.v12-tab');for(var i=0;i<tabs.length;i++){tabs[i].addEventListener('click',function(){var key=this.getAttribute('data-v12-tab');for(var j=0;j<tabs.length;j++)tabs[j].classList.remove('active');this.classList.add('active');var panes=document.querySelectorAll('.v12-pane');for(var k=0;k<panes.length;k++)panes[k].classList.toggle('active',panes[k].getAttribute('data-v12-pane')===key);});}var backdrop=document.getElementById('v12EditorBackdrop');if(backdrop)backdrop.addEventListener('click',function(e){if(e.target===backdrop)v12CloseEditor()});document.addEventListener('keydown',function(e){if(e.key==='Escape')v12CloseEditor();if((e.ctrlKey||e.metaKey)&&e.shiftKey&&String(e.key).toLowerCase()==='e'){e.preventDefault();v12OpenEditor()}});var lf=document.getElementById('v12LogoFile');if(lf)lf.addEventListener('change',function(){if(!this.files||!this.files[0])return;var r=new FileReader();r.onload=function(ev){document.getElementById('v12LogoPreview').src=ev.target.result};r.readAsDataURL(this.files[0])});}
